//! The partial render's background-object load shader: Mesa 26.2.1 pco's
//! output of `pvr_uscgen_spm_load()` (src/imagination/vulkan/pvr_usc.c, MIT)
//! for `pvr_spm_load_props` { output_reg_count 1, tile_buffer_count 0,
//! is_multisampled 0 } on BXS-4-64 (36.53.104.796). The words are
//! tools/pco_shc/spm_load/spm_load.hex, the counts its spm_load.meta.txt
//! (generated by tools/pco_shc/gen_spm_load.py; the host test
//! `spm_load_blob_matches_its_generator` compares them). Do not edit by hand.
//!
//! It samples the SPM scratch once per pixel through the sampler (sh0-3)
//! and image (sh4-7) words the PR background PDS DMAs into the common store,
//! and writes the raw dword to output register 0
//! (docs/notes/pvr-pr-spm-const.md).

/// The shader's entry: its byte offset in [`SPM_LOAD_USC`] (meta
/// `entry_offset`).
pub(super) const SPM_LOAD_ENTRY: u32 = 0;
/// The temporaries a pixel instance needs (meta `temps`): the DOUTU's count.
pub(super) const SPM_LOAD_TEMPS: u32 = 6;
/// The shared registers it reads (meta `consts_dwords`): sampler sh0-3, image
/// sh4-7.
pub(super) const SPM_LOAD_CONSTS_DWORDS: u32 = 8;
/// The machine code, 50 dwords (200 bytes, meta `usc_bytes`), little-endian,
